+        // Добавляем функционал для увеличения изображений
+        document.addEventListener('click', function(event) {
+            // Проверяем, является ли клик по изображению в контейнере
+            if (event.target.classList.contains('image-container') || event.target.closest('.image-container')) {
+                const img = event.target.tagName === 'IMG' ? event.target : event.target.querySelector('img');
+                if (img) {
+                    openImageModal(img.src, img.alt);
+                }
+            }
+        });
+
+        // Функция для открытия модального окна с изображением
+        function openImageModal(src, alt) {
+            // Удаляем предыдущее модальное окно, если оно существует
+            const existingModal = document.querySelector('.modal');
+            if (existingModal) existingModal.remove();
+
+            // Создаем модальное окно
+            const modal = document.createElement('div');
+            modal.className = 'modal';
+            modal.innerHTML = `
+                <span class="close">&times;</span>
+                <img class="modal-content" src="${src}" alt="${alt}">
+            `;
+
+            // Добавляем модальное окно в документ
+            document.body.appendChild(modal);
+
+            // Находим элементы модального окна
+            const modalImg = modal.querySelector('.modal-content');
+            const closeModal = modal.querySelector('.close');
+
+            // Обработчики закрытия
+            closeModal.onclick = function() {
+                modal.style.display = 'none';
+            };
+            
+            modal.onclick = function() {
+                modal.style.display = 'none';
+            };
+
+            // Отображаем модальное окно
+            modal.style.display = 'block';
+        }
     </script>
